import { Suspense, use } from 'react';

const cache = new Map<string, Promise<any>>();
function load(id: string) {
  if (!cache.has(id)) cache.set(id, fetch(`{{endpoint}}/${id}`).then(r => r.json()));
  return cache.get(id)!;
}

function Inner({ id }: { id: string }) {
  const data = use(load(id));
  return <pre>{JSON.stringify(data, null, 2)}</pre>;
}

export function {{component_name}}({ id }: { id: string }) {
  return <Suspense fallback={<div>loading…</div>}><Inner id={id} /></Suspense>;
}
